class Solution {
    int memo[2005][2005];
    int solve(const std::vector<int>& nums, int target) {
        int n = nums.size();
        std::memset(memo, -1, sizeof(memo));
        auto dp = [&](auto& self, int i, int j) -> int {
            if (j - i + 1 < 2) return 0;
            if (memo[i][j] != -1) return memo[i][j];
            int res = 0;
            if (nums[i] + nums[i + 1] == target) res = std::max(res, 1 + self(self, i + 2, j));
            if (nums[j - 1] + nums[j] == target) res = std::max(res, 1 + self(self, i, j - 2));
            if (nums[i] + nums[j] == target) res = std::max(res, 1 + self(self, i + 1, j - 1));
            return memo[i][j] = res;
        };
        return dp(dp, 0, n - 1);
    }
