import java.util.*;

class Solution {
    private int[][] memo;
    private int solve(int[] nums, int target) {
        int n = nums.length;
        memo = new int[n][n];
        for (int[] row : memo) Arrays.fill(row, -1);
        return dp(nums, 0, n - 1, target);
    }

    private int dp(int[] nums, int i, int j, int target) {
        if (j - i + 1 < 2) return 0;
        if (memo[i][j] != -1) return memo[i][j];
        int res = 0;
        if (nums[i] + nums[i + 1] == target) res = Math.max(res, 1 + dp(nums, i + 2, j, target));
        if (nums[j - 1] + nums[j] == target) res = Math.max(res, 1 + dp(nums, i, j - 2, target));
        if (nums[i] + nums[j] == target) res = Math.max(res, 1 + dp(nums, i + 1, j - 1, target));
        return memo[i][j] = res;
    }

    public int maxOperations(int[] nums) {
        int n = nums.length;
        Set<Integer> candidates = new HashSet<>(Arrays.asList(
            nums[0] + nums[1],
            nums[n - 2] + nums[n - 1],
            nums[0] + nums[n - 1]
        ));
        int ans = 0;
        for (int c : candidates) ans = Math.max(ans, solve(nums, c));
        return ans;
    }
}

var maxOperations = function(nums) {
    const n = nums.length;
    const candidates = new Set([
        nums[0] + nums[1],
        nums[n - 2] + nums[n - 1],
        nums[0] + nums[n - 1]
    ]);
    const solve = (target) => {
        const memo = new Map();
        const dp = (i, j) => {
            if (j - i + 1 < 2) return 0;
            const key = (i << 12) | j;
            if (memo.has(key)) return memo.get(key);
            let res = 0;
            if (nums[i] + nums[i + 1] === target) res = Math.max(res, 1 + dp(i + 2, j));
            if (nums[j - 1] + nums[j] === target) res = Math.max(res, 1 + dp(i, j - 2));
            if (nums[i] + nums[j] === target) res = Math.max(res, 1 + dp(i + 1, j - 1));
            memo.set(key, res);
            return res;
        };
        return dp(0, n - 1);
    };
    let ans = 0;
    for (const c of candidates) ans = Math.max(ans, solve(c));
    return ans;
};
